<script setup lang="ts">
import {useCardText} from '../text'
import {dateTime,displayName} from '../format'
import type {ReportRow} from './types'
defineProps<{rows:ReportRow[];timezone:string;disabled?:boolean}>();const emit=defineEmits<{select:[row:ReportRow]}>(),{t,locale}=useCardText(),x=(zh:string,en:string)=>locale.value.startsWith('en')?en:zh
const unit=(v:string)=>v==='card'?x('张','cards'):v==='stamp'?x('次集次','stamps'):v
</script>
<template><div class="cards-table-scroll"><table class="cards-data-table card-business-rows"><thead><tr><th>{{x('办理时间 / 业务日期','Handled / business date')}}</th><th>{{t('customer')}}</th><th>{{t('plans')}}</th><th>{{x('业务 / 数量','Activity / quantity')}}</th><th>{{x('权益 / 集次变化','Entitlement / stamp change')}}</th><th>{{t('status')}}</th><th>{{t('details')}}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><span>{{row.createdAt?dateTime(row.createdAt,timezone):x('按日计算','Calculated daily')}}</span><small>{{x('业务日期','Business date')}} {{row.businessDay}}</small></td><td><strong>{{row.customerName||t('customerUnavailable')}}</strong><small>{{row.customerPhone||'—'}}</small></td><td><strong>{{displayName(row,locale)}}</strong><small>{{locale.startsWith('en')?(row.productEn||row.productZh):row.productZh}}</small></td><td>{{t(row.kind==='stamp'?'stampAction':row.kind)}}<strong>{{row.quantity}} {{unit(row.unit)}}</strong></td><td><template v-if="row.beforeTotal===null&&row.afterTotal===null">{{x('不适用','Not applicable')}}</template><template v-else><small v-if="['stamp','stamp_reverse'].includes(row.kind)">{{x('集次进度','Stamp progress')}}</small>{{row.beforeTotal??'—'}} → {{row.afterTotal??'—'}}</template></td><td>{{row.id.startsWith('expiry:')?x('按日计算','Calculated'):row.reversed?x('已冲正 / 撤回','Reversed'):row.kind==='daily_expire'?x('已结算','Settled'):x('已记账','Recorded')}}</td><td><button type="button" :disabled="disabled" @click="emit('select',row)">{{t('details')}}</button></td></tr></tbody></table></div></template>
